exercises.reference_solution:
def double_value(x):
    result = x * 2
    return result

def even_or_odd(n):
    if n % 2 == 0:
        return 'even'
    return 'odd'

def count_positives(nums):
    count = 0
    for x in nums:
        if x > 0:
            count += 1
    return count

def find_max(nums):
    if isinstance(nums, int):
        return nums
    best = nums[0]
    for x in nums[1:]:
        if x > best:
            best = x
    return best

def sum_list(elements):
    total = 0
    for x in elements:
        total += x
    return total

def find_index(elements, target):
    for i, x in enumerate(elements):
        if x == target:
            return i
    return -1

def build_counts(items):
    counts = {}
    for x in items:
        counts[x] = counts.get(x, 0) + 1
    return counts
